const densityMap = {
  "drifting mist": 600,
  "compact cluster": 800,
  "surging river": 1000,
  "dense smoke": 1200,
  "swarming vortex": 1500,
  "black hole": 1800
};

const predatorMap = {
  "lazy circling": { speed: 3, radius: 60, scatter: 0.5 },
  "curious stalker": { speed: 4, radius: 90, scatter: 1.0 },
  "slicing passes": { speed: 6, radius: 120, scatter: 1.5 },
  "relentless dive": { speed: 8, radius: 150, scatter: 2.5 },
  "frenzied raptor": { speed: 11, radius: 200, scatter: 4.0 },
  "shattering bolt": { speed: 15, radius: 300, scatter: 6.0 }
};

const currentMap = {
  "still dusk": { force: 0.01, twitch: 0 },
  "gentle thermals": { force: 0.05, twitch: 0.05 },
  "crosswind gust": { force: 0.1, twitch: 0.1 },
  "choppy gale": { force: 0.2, twitch: 0.2 },
  "whirling squall": { force: 0.4, twitch: 0.5 },
  "tornadic shear": { force: 0.8, twitch: 0.9 }
};

const glowMap = {
  "ink silhouettes": { bg: [240, 240, 245, 255], fg: "#111", trail: 255, ring: "#333" },
  "graphite shimmer": { bg: [200, 205, 210, 200], fg: "#445", trail: 150, ring: "#667" },
  "dusk embers": { bg: [30, 20, 25, 100], fg: "#f63", trail: 80, ring: "#f31" },
  "phosphor trails": { bg: [5, 10, 15, 40], fg: "#0f8", trail: 40, ring: "#0fa" },
  "neon ionization": { bg: [10, 5, 20, 20], fg: "#f0f", trail: 20, ring: "#0ff" },
  "solar flare": { bg: [255, 250, 240, 15], fg: "#fa0", trail: 10, ring: "#f00" }
};

const geoMap = {
  "soft grains": "circle",
  "needle strokes": "line",
  "chevron darts": "chevron",
  "filament ribbons": "ribbon",
  "faceted prisms": "prism",
  "shards of glass": "shard"
};

let boids = [];
let maxBoids = 1800;
let predator = { x: 400, y: 400, vx: 0, vy: 0, tx: 400, ty: 400 };

const cols = 20;
const rows = 20;
const cellSize = 40;
let gridHeads = new Int16Array(cols * rows);
let gridNext = new Int16Array(maxBoids);

p.setup = function() {
  p.createCanvas(800, 800);
  p.noSmooth();
  for (let i = 0; i < maxBoids; i++) {
    boids.push({
      x: p.random(800), y: p.random(800),
      vx: p.random(-2, 2), vy: p.random(-2, 2)
    });
  }
};

p.draw = function() {
  const dVal = p.getSynthVar("flock_density") || "drifting mist";
  const pVal = p.getSynthVar("predator_fury") || "lazy circling";
  const cVal = p.getSynthVar("aerial_current") || "still dusk";
  const gVal = p.getSynthVar("plumage_glow") || "ink silhouettes";
  const wVal = p.getSynthVar("wing_geometry") || "soft grains";

  const activeBoids = densityMap[dVal];
  const predConfig = predatorMap[pVal];
  const currConfig = currentMap[cVal];
  const glowConfig = glowMap[gVal];
  const geoConfig = geoMap[wVal];

  const ctx = p.drawingContext;

  ctx.fillStyle = `rgba(${glowConfig.bg[0]}, ${glowConfig.bg[1]}, ${glowConfig.bg[2]}, ${glowConfig.trail / 255})`;
  ctx.fillRect(0, 0, 800, 800);

  predator.tx = p.mouseX > 0 ? p.mouseX : p.noise(p.frameCount * 0.01) * 800;
  predator.ty = p.mouseY > 0 ? p.mouseY : p.noise(p.frameCount * 0.01 + 100) * 800;
  let pdx = predator.tx - predator.x;
  let pdy = predator.ty - predator.y;
  let plen = Math.sqrt(pdx*pdx + pdy*pdy) || 1;
  predator.vx += (pdx / plen) * 0.5;
  predator.vy += (pdy / plen) * 0.5;
  predator.vx *= 0.95; predator.vy *= 0.95;

  let pSpd = Math.sqrt(predator.vx*predator.vx + predator.vy*predator.vy) || 1;
  if (pSpd > predConfig.speed) {
    predator.vx = (predator.vx / pSpd) * predConfig.speed;
    predator.vy = (predator.vy / pSpd) * predConfig.speed;
  }
  predator.x += predator.vx;
  predator.y += predator.vy;
  if (predator.x < 0) predator.x = 800;
  if (predator.x > 800) predator.x = 0;
  if (predator.y < 0) predator.y = 800;
  if (predator.y > 800) predator.y = 0;

  gridHeads.fill(-1);
  for (let i = 0; i < activeBoids; i++) {
    let b = boids[i];
    let cx = Math.floor(b.x / cellSize);
    let cy = Math.floor(b.y / cellSize);
    cx = Math.max(0, Math.min(cols - 1, cx));
    cy = Math.max(0, Math.min(rows - 1, cy));
    let idx = cx + cy * cols;
    gridNext[i] = gridHeads[idx];
    gridHeads[idx] = i;
  }

  ctx.beginPath();
  ctx.strokeStyle = glowConfig.fg;
  ctx.fillStyle = glowConfig.fg;
  ctx.lineWidth = 1.5;

  let twitchPhase = p.frameCount * 0.5;

  for (let i = 0; i < activeBoids; i++) {
    let b = boids[i];

    let cx = Math.floor(b.x / cellSize);
    let cy = Math.floor(b.y / cellSize);
    let alignX = 0, alignY = 0, sepX = 0, sepY = 0, cohX = 0, cohY = 0, count = 0;

    for (let y = Math.max(0, cy - 1); y <= Math.min(rows - 1, cy + 1); y++) {
      for (let x = Math.max(0, cx - 1); x <= Math.min(cols - 1, cx + 1); x++) {
        let curr = gridHeads[x + y * cols];
        while (curr !== -1) {
          if (curr !== i) {
            let ob = boids[curr];
            let dx = b.x - ob.x;
            let dy = b.y - ob.y;
            let dsq = dx*dx + dy*dy;
            if (dsq < 1600) { 
              alignX += ob.vx; alignY += ob.vy;
              cohX += ob.x; cohY += ob.y;
              if (dsq < 400 && dsq > 0) { 
                sepX += dx / dsq; sepY += dy / dsq;
              }
              count++;
            }
          }
          curr = gridNext[curr];
        }
      }
    }

    if (count > 0) {
      alignX /= count; alignY /= count;
      cohX /= count; cohY /= count;
      b.vx += (alignX - b.vx) * 0.05;
      b.vy += (alignY - b.vy) * 0.05;
      b.vx += (cohX - b.x) * 0.005;
      b.vy += (cohY - b.y) * 0.005;
      b.vx += sepX * 2.0;
      b.vy += sepY * 2.0;
    }

    let pfdx = b.x - predator.x;
    let pfdy = b.y - predator.y;
    let pfd = Math.sqrt(pfdx*pfdx + pfdy*pfdy) || 0.001;
    if (pfd < predConfig.radius) {
      b.vx += (pfdx / pfd) * predConfig.scatter;
      b.vy += (pfdy / pfd) * predConfig.scatter;
      if (Math.random() < 0.05 && glowConfig.trail < 100) {
        ctx.moveTo(b.x + 5, b.y);
        ctx.arc(b.x, b.y, 5, 0, Math.PI * 2);
      }
    }

    let wind = Math.sin(b.y * 0.01 + p.frameCount * 0.02);
    b.vx += wind * currConfig.force;
    if (currConfig.twitch > 0 && Math.random() < 0.1) {
      b.vx += Math.sin(twitchPhase + b.x) * currConfig.twitch;
      b.vy += Math.cos(twitchPhase + b.y) * currConfig.twitch;
    }

    let margin = 50, turn = 0.5;
    if (b.x < margin) b.vx += turn;
    if (b.x > 800 - margin) b.vx -= turn;
    if (b.y < margin) b.vy += turn;
    if (b.y > 800 - margin) b.vy -= turn;

    let speed = Math.sqrt(b.vx*b.vx + b.vy*b.vy) || 1;
    let limit = 4;
    if (speed > limit) {
      b.vx = (b.vx / speed) * limit;
      b.vy = (b.vy / speed) * limit;
    }

    b.x += b.vx;
    b.y += b.vy;

    let dir = Math.atan2(b.vy, b.vx);
    let size = 4;

    if (geoConfig === "circle") {
      ctx.moveTo(b.x, b.y);
      ctx.rect(b.x - 1.5, b.y - 1.5, 3, 3);
    } else if (geoConfig === "line") {
      ctx.moveTo(b.x, b.y);
      ctx.lineTo(b.x - b.vx * 2, b.y - b.vy * 2);
    } else if (geoConfig === "chevron") {
      let nx = Math.cos(dir + 2.5) * size;
      let ny = Math.sin(dir + 2.5) * size;
      ctx.moveTo(b.x + Math.cos(dir)*size, b.y + Math.sin(dir)*size);
      ctx.lineTo(b.x + nx, b.y + ny);
      ctx.lineTo(b.x + Math.cos(dir - 2.5)*size, b.y + Math.sin(dir - 2.5)*size);
    } else if (geoConfig === "ribbon") {
      ctx.moveTo(b.x, b.y);
      ctx.bezierCurveTo(b.x - b.vx*2, b.y - b.vy*2 + 5, b.x - b.vx*4, b.y - b.vy*4 - 5, b.x - b.vx*5, b.y - b.vy*5);
    } else if (geoConfig === "prism") {
      ctx.moveTo(b.x - size, b.y - size);
      ctx.lineTo(b.x + size, b.y - size);
      ctx.lineTo(b.x, b.y + size);
      ctx.lineTo(b.x - size, b.y - size);
    } else { 
      ctx.moveTo(b.x + Math.cos(dir)*size*1.5, b.y + Math.sin(dir)*size*1.5);
      ctx.lineTo(b.x + Math.cos(dir + 2.0)*size*0.5, b.y + Math.sin(dir + 2.0)*size*0.5);
      ctx.lineTo(b.x + Math.cos(dir - 2.0)*size*0.5, b.y + Math.sin(dir - 2.0)*size*0.5);
    }
  }

  if (geoConfig === "circle") {
    ctx.fill();
    ctx.stroke();
  } else {
    ctx.stroke();
  }

  ctx.beginPath();
  ctx.fillStyle = glowConfig.ring;
  ctx.arc(predator.x, predator.y, 6, 0, Math.PI * 2);
  ctx.fill();
};
